package synth

import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

class Counter260 {
    var current: Int by Delegates.observable(52) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
data class Pair261<A, B>(val first: A, val second: B)

fun combine261(left: Int, right: Int): Pair261<Int, Int> {
    return Pair261(left + 59, right + 19)
}
sealed class Outcome262 {
    data class Success(val payload: String) : Outcome262()
    data object Failure : Outcome262()
}

fun describe262(outcome: Outcome262): String = when (outcome) {
    is Outcome262.Success -> outcome.payload
    Outcome262.Failure -> "failed"
}
